def legendre_symbol(a, p):
    if a % p == 0:
        return 0
    if pow(a, (p-1)//2, p) == 1:
        return 1
    return -1

n = 13
# Quadratic residues mod 13
qr = set()
for i in range(1, n):
    qr.add((i*i) % n)
print("Quadratic residues mod 13:", sorted(qr))

x = [legendre_symbol(i, n) if i != 0 else 1 for i in range(n)]
print("Legendre sequence x:", x)
print("Sum x:", sum(x))

def check_legendre_pair(x, y, n=13):
    if sum(x) != 1 or sum(y) != 1:
        return False
    for k in range(1, (n+1)//2):
        corr = 0
        for i in range(n):
            corr += x[i] * x[(i+k) % n]
            corr += y[i] * y[(i+k) % n]
        if corr != -2:
            return False
    return True

